/**
 * dsh-provider-usage — 用量统计拉取、缓存管理与互斥锁服务。
 *
 * 注册能力经实例调用（#768 B2：模型配置与适配器状态读写收进 AdapterRegistry
 * 实例方法，本域不直引 registry 门面值边；类型经门面以 type 复用）。
 */
import { rename, writeFile } from "node:fs/promises";
import type { Context } from "@deepseek-ai/cordis";
import { Mutex } from "async-mutex";
import { errorMessage } from "../../../../../shared/host-utils.js";
import type { NormalizedConfig } from "../../shared/interface.ts";
import type { HistoryStore } from "../history/interface.ts";
import {
  runV2Pipeline,
  runV2PanelPipeline,
  panelCacheKey,
  isPanelCacheStale,
  type PanelCacheEntry,
  type V2PipelineResult,
} from "./v2.ts";
import type { AdapterRegistry } from "../registry/interface.ts";
import type { UsageStatsAdapter } from "../../shared/interface.ts";
import type { UserAdapterRecord } from "../registry/interface.ts";

export interface StatsServiceOptions {
  ctx: Context;
  config: NormalizedConfig;
  historyRoot: string;
  registry: AdapterRegistry;
  history: HistoryStore;
  sanitizeDiagnostic: (s: string) => string;
  recordAdapterStateDiagnostic: (message: string) => void;
}

export class StatsService {
  readonly ctx: Context;
  readonly config: NormalizedConfig;
  readonly historyRoot: string;
  readonly registry: AdapterRegistry;
  readonly history: HistoryStore;
  readonly sanitizeDiagnostic: (s: string) => string;
  readonly recordAdapterStateDiagnostic: (message: string) => void;

  readonly cache = new Map<string, V2PipelineResult>();
  readonly panelCache = new Map<string, PanelCacheEntry>();
  readonly providerLocks = new Map<string, Mutex>();

  // 缓存纪元——任何「清理缓存」入口递增 generation，
  // 在途 getStats 完成后校验纪元未变才 set，防「选择切换×在途取数」交错污染新缓存。
  private cacheGeneration = 0;
  /** 面板管道 in-flight 去重（同 key 并发 miss 共享一次执行）。 */
  private readonly panelInFlight = new Map<
    string,
    Promise<{ panelHtml?: string; error?: string }>
  >();

  private stateChain: Promise<void> = Promise.resolve();

  constructor(options: StatsServiceOptions) {
    this.ctx = options.ctx;
    this.config = options.config;
    this.historyRoot = options.historyRoot;
    this.registry = options.registry;
    this.history = options.history;
    this.sanitizeDiagnostic = options.sanitizeDiagnostic;
    this.recordAdapterStateDiagnostic = options.recordAdapterStateDiagnostic;
  }

  lockOf(provider: string): Mutex {
    let m = this.providerLocks.get(provider);
    if (m === undefined) {
      m = new Mutex();
      this.providerLocks.set(provider, m);
    }
    return m;
  }

  cacheFresh(provider: string): V2PipelineResult | undefined {
    const entry = this.cache.get(provider);
    if (entry === undefined) return undefined;
    if (Date.now() - entry.fetchedAt > this.config.cacheDurationMs) {
      this.cache.delete(provider);
      return undefined;
    }
    return entry;
  }

  /** 只读观测口（health 响应字段名 cacheSize 保持，语义与直读 Map.size 等价）。 */
  cacheSize(): number {
    return this.cache.size;
  }

  /** 全量清理（select/add/热更等选择变更挂点）：纪元失效防在途结果写回。 */
  purgeAllCaches(): void {
    this.cacheGeneration += 1;
    this.cache.clear();
    this.panelCache.clear();
  }

  purgePanelCacheForProvider(provider: string): void {
    const prefix = `${provider}\u0000`;
    for (const key of this.panelCache.keys()) {
      if (key.startsWith(prefix)) this.panelCache.delete(key);
    }
  }

  purgeCachesForProviders(providers: Iterable<string>): void {
    this.cacheGeneration += 1;
    for (const p of providers) {
      this.cache.delete(p);
      this.purgePanelCacheForProvider(p);
    }
  }

  /**
   * D7 面板结果（深模块）：key 归一 → 命中判定 → miss 删除 → 管道执行 → 失败不写。
   * 同 key 并发 miss 共享 in-flight（不双跑 formatPanel）；错误/无结果不入缓存。
   */
  async getPanelResult(
    provider: string,
    entry: { name: string; adapter: UsageStatsAdapter },
    range: { start: number; end: number },
  ): Promise<{ panelHtml?: string; error?: string }> {
    const cacheKey = panelCacheKey(provider, entry.name, range);
    const hit = this.panelCache.get(cacheKey);
    if (hit !== undefined && !isPanelCacheStale(hit, Date.now())) {
      return { panelHtml: hit.panelHtml, error: hit.error };
    }

    const inflight = this.panelInFlight.get(cacheKey);
    if (inflight !== undefined) return inflight;

    const run = (async (): Promise<{ panelHtml?: string; error?: string }> => {
      this.panelCache.delete(cacheKey);
      const result = await runV2PanelPipeline({
        adapter: entry.adapter,
        provider,
        history: this.history,
        range,
        timeoutMs: this.config.fetchTimeoutMs,
      });
      if (result.error === undefined) {
        this.panelCache.set(cacheKey, {
          panelHtml: result.panelHtml,
          error: result.error,
          at: Date.now(),
        });
      }
      return result;
    })().finally(() => {
      this.panelInFlight.delete(cacheKey);
    });
    this.panelInFlight.set(cacheKey, run);
    return run;
  }

  warmupProviders(providers: Iterable<string>): void {
    for (const p of providers) {
      if (this.registry.getEntry(p) !== undefined) {
        void this.getStats(p).catch(() => {});
      }
    }
  }

  scheduleWriteAdapterState(override?: Record<string, string | null>): void {
    this.stateChain = this.stateChain
      .catch(() => {})
      .then(async () => {
        const saved = await this.registry.readAdapterStateResult(this.historyRoot, {
          diagnostic: this.recordAdapterStateDiagnostic,
        });
        if (saved.status === "unreadable") {
          throw new Error(
            `读取旧 adapter-state.json 失败（${saved.detail ?? "未知错误"}），为避免覆盖旧状态已取消写入`,
          );
        }
        const merged: Record<string, string | null> = { ...saved.state };
        for (const [provider, name] of Object.entries(this.registry.snapshot().enabled))
          merged[provider] = name;
        if (override !== undefined) Object.assign(merged, override);
        await this.registry.writeAdapterState(this.historyRoot, merged, (message) =>
          this.recordAdapterStateDiagnostic(this.sanitizeDiagnostic(message)),
        );
      })
      .catch((error: unknown) => {
        const detail = this.sanitizeDiagnostic(errorMessage(error));
        console.error(`[dsh-provider-usage] 启用选择落盘失败：${detail}`);
        this.registry.recordError("adapter-state", "load", `启用选择落盘失败：${detail}`);
      });
  }

  async persistUserAdapter(rec: UserAdapterRecord): Promise<void> {
    const write = async (): Promise<void> => {
      const list = await this.registry.readUserAdapters(this.historyRoot);
      if (list.some((r) => r.id === rec.id)) return;
      list.push(rec);
      const tmp = `${this.registry.userAdaptersFile(this.historyRoot)}.${Date.now()}.tmp`;
      await writeFile(tmp, JSON.stringify({ version: 1, adapters: list }), { mode: 0o600 });
      await rename(tmp, this.registry.userAdaptersFile(this.historyRoot));
    };
    try {
      await (this.stateChain = this.stateChain.then(write));
    } catch (e: unknown) {
      this.registry.recordError(
        "user-adapters",
        "load",
        `清单落盘失败：${e instanceof Error ? e.message : String(e)}`,
      );
    }
  }

  async getStats(provider: string, signal?: AbortSignal): Promise<V2PipelineResult> {
    const cached = this.cacheFresh(provider);
    if (cached !== undefined) return { ...cached, status: "cached" };

    return this.lockOf(provider).runExclusive(async () => {
      const cachedInLock = this.cacheFresh(provider);
      if (cachedInLock !== undefined) return { ...cachedInLock, status: "cached" };

      // 纪元快照：在途期间若发生清理（select/热更/全清），完成后不再写回旧结果
      const gen = this.cacheGeneration;
      const entry = this.registry.getEntry(provider);
      if (entry === undefined) {
        const code = this.registry.hasCandidates(provider) ? "no-enabled-adapter" : "no-adapter";
        const result: V2PipelineResult = {
          ok: false,
          configured: false,
          reason: code,
          error: null,
          fetchedAt: Date.now(),
          provider,
          adapterName: provider,
          status: "stale",
        };
        if (this.cacheGeneration === gen) this.cache.set(provider, result);
        return result;
      }

      const providerConfig = await this.registry.resolveProviderConfig(provider, this.ctx, {
        apiEndpoint: this.config.apiEndpoint || undefined,
        apiKey: this.config.apiKey || undefined,
      });

      const result = await runV2Pipeline({
        adapter: entry.adapter,
        provider,
        config: { apiEndpoint: providerConfig.apiEndpoint, apiKey: providerConfig.apiKey },
        staticPath: this.config.staticPath,
        timeoutMs: this.config.fetchTimeoutMs,
        signal,
        history: this.history,
      });

      if (result.ok && result.status === "fresh" && result.rawData !== undefined) {
        const historyEntry = { time: result.fetchedAt, data: result.rawData };
        await this.history.append(provider, entry.name, historyEntry).catch(() => {});
        this.purgePanelCacheForProvider(provider);
      }

      if (this.cacheGeneration === gen) this.cache.set(provider, result);
      return result;
    });
  }

  dispose(): void {
    for (const lock of this.providerLocks.values()) lock.cancel();
    this.providerLocks.clear();
    this.cache.clear();
    this.panelCache.clear();
  }
}

/**
 * dsh-provider-usage — v2 新契约管道（独立文件，不膨胀 collectStats）。
 *
 * 职责：
 * 1. 组装 fetchData 入参（apiEndpoint/staticPath/apiKey/provider/timeoutMs/signal）
 * 2. safeFetchData 执行（5s 固定超时 + 序列化校验 + 错误隔离）
 * 3. 落盘历史（按天分片 JSONL）
 * 4. safeFormat 执行 formatCapsule（宿主端渲染 HTML）
 * 5. 返回归一化结果（含 status/capsuleHtml）
 *
 * 纪律：所有用户函数调用经 safe* 包装，错误不外抛。
 */
import type { UsageStatsAdapter, FetchContext } from "../../shared/interface.ts";
import { esc } from "../../shared/interface.ts";
import { ADAPTER_UTILS } from "../../shared/interface.ts";
import type { HistoryStore } from "../history/interface.ts";
import { safeFetchData, safeFormat } from "./guards.ts";
import { sanitizeHtml } from "../../shared/interface.ts";

/** v2 管道执行结果。 */
export interface V2PipelineResult {
  ok: boolean;
  configured: boolean;
  reason: string | null;
  error: string | null;
  fetchedAt: number;
  provider: string;
  adapterName: string;
  status: "fresh" | "cached" | "stale";
  capsuleHtml?: string;
  /** 拉取到的原始数据（供历史落盘）。 */
  rawData?: Record<string, unknown>;
}

/** v2 管道执行上下文。 */
export interface V2PipelineContext {
  adapter: UsageStatsAdapter;
  provider: string;
  /** 插件解析出的 provider 配置（apiEndpoint + apiKey）。 */
  config: {
    apiEndpoint?: string;
    apiKey?: string;
  };
  /** 用户定义的 API 路径。 */
  staticPath: string;
  timeoutMs: number;
  /** 附加给 fetchData 的上下文（model/sessionId）。 */
  meta?: { model?: string; sessionId?: string };
  /** 注入的 fetch 实现（测试可替换）。 */
  fetchImpl?: typeof fetch;
  signal?: AbortSignal;
  /**
   * 历史存储（可选注入）：取数失败时读取最后一条成功数据供胶囊「带值降级」渲染。
   * 错误帧绝不以 fresh 身份进历史，故 last 即最后一条成功帧；不传则维持空 data 占位行为。
   */
  history?: Pick<HistoryStore, "last">;
  /** 共享图表工具注入（缺省回退 ADAPTER_UTILS）。 */
  utils?: import("../../shared/interface.ts").AdapterUtils;
}

/**
 * 执行一次 v2 管道：拉取 → 落盘 → 格式化胶囊。
 * 无外部异常抛出（全部约束在返回结构内）。
 */
export async function runV2Pipeline(ctx: V2PipelineContext): Promise<V2PipelineResult> {
  const { adapter, provider } = ctx;
  const fetchedAt = Date.now();

  // fail-fast：管道内部组装断言——组装前提非法时不发起任何取数，
  // 直接产出既有 error 帧（stale + error），不让请求悬挂。这是管线自身的防御性
  // 检查，不是对用户适配器的契约行为约束（不改 FetchContext 契约、不新增配置项）。
  if (!(Number.isFinite(ctx.timeoutMs) && ctx.timeoutMs > 0)) {
    return {
      ok: false,
      configured: true,
      reason: "fetch-failed",
      error: `pipeline 组装非法：timeoutMs=${ctx.timeoutMs}`,
      fetchedAt,
      provider,
      adapterName: adapter.name,
      status: "stale",
    };
  }

  // 1. 组装 fetchData 入参（signal 由下方 safeFetchData 以合并信号注入，此处不预置；
  //    utils 一律强制注入 ADAPTER_UTILS——内置 mjs 与用户 mjs 均可消费共享图表工具）
  const fetchCtx: FetchContext = {
    apiEndpoint: ctx.config.apiEndpoint ?? "",
    staticPath: ctx.staticPath,
    apiKey: ctx.config.apiKey,
    provider,
    model: ctx.meta?.model,
    sessionId: ctx.meta?.sessionId,
    timeoutMs: ctx.timeoutMs,
    utils: ctx.utils ?? ADAPTER_UTILS,
  };

  // 2. safeFetchData（5s 固定超时 + 序列化 + 错误隔离）。
  // 闭包接收合并信号（超时兜底 × ctx.signal 外部信号，手动级联合流）
  // 并放进 adapter.fetchData 入参——适配器把 ctx.signal 透传给底层 fetch 即获得真取消能力
  // （deepseek-official 直传 fetch、opencode-go 监听 signal 均立即受益）；
  // 0 参 fetchData 忽略入参不受影响。
  const fetched = await safeFetchData(
    async (signal) => {
      const fetcher: typeof fetch = ctx.fetchImpl ?? fetch;
      return adapter.fetchData({ ...fetchCtx, signal, fetch: fetcher } as unknown as FetchContext);
    },
    ctx.timeoutMs,
    ctx.signal,
  );

  if (fetched.error !== undefined) {
    // 取数失败仍产出 stale 胶囊 + status:'stale' + error；
    // 不带 rawData → 上层不落盘历史（错误帧绝不以 fresh 身份进历史）。
    // 带值降级：注入 history 时读取最后一条成功数据喂给 formatCapsule——
    // 数值部分始终渲染最后成功值（避免健康值跌成 "--"），数据来源状态交给
    // 客户端圆点颜色表达（dou-dot-warn 黄点 = 陈旧降级，见 client pillDotLevel）。
    // history 读取失败视同无历史（空 data 占位），绝不因兜底读失败而改变错误帧语义。
    let failData: Record<string, unknown> = {};
    if (ctx.history !== undefined) {
      const lastEntry = await ctx.history.last(provider, adapter.name).catch(() => null);
      if (lastEntry !== null && lastEntry.data && typeof lastEntry.data === "object") {
        failData = lastEntry.data;
      }
    }
    const failCapsInput = {
      time: fetchedAt,
      data: failData,
      status: "stale" as const,
      error: fetched.error,
      esc,
    };
    const failFormatted = await safeFormat(
      () => adapter.formatCapsule(failCapsInput),
      "formatCapsule",
      ctx.timeoutMs,
    );
    const failCapsuleHtml =
      failFormatted.html !== undefined ? sanitizeHtml(failFormatted.html) : undefined;
    return {
      ok: false,
      configured: true,
      reason: "fetch-failed",
      error: fetched.error,
      fetchedAt,
      provider,
      adapterName: adapter.name,
      status: "stale",
      ...(failCapsuleHtml !== undefined ? { capsuleHtml: failCapsuleHtml } : {}),
    };
  }

  // 3. 落盘历史（按天分片 JSONL；失败不阻断展示，只记日志）
  const data = fetched.data ?? {};
  const capsInput = {
    time: fetchedAt,
    data,
    status: "fresh" as const,
    esc,
  };

  // 4. safeFormat formatCapsule（宿主端渲染 HTML）+ 净化
  const formatted = await safeFormat(
    () => adapter.formatCapsule(capsInput),
    "formatCapsule",
    ctx.timeoutMs,
  );
  const capsuleHtml = formatted.html !== undefined ? sanitizeHtml(formatted.html) : undefined;

  return {
    ok: true,
    configured: true,
    reason: null,
    error: null,
    fetchedAt,
    provider,
    adapterName: adapter.name,
    status: "fresh",
    capsuleHtml,
    rawData: data,
  };
}

/** v2 面板管道：查询历史（全量）→ formatPanel → HTML。 */
export async function runV2PanelPipeline(opts: {
  adapter: UsageStatsAdapter;
  provider: string;
  history: HistoryStore;
  range: { start: number; end: number };
  timeoutMs?: number;
}): Promise<{ panelHtml?: string; error?: string }> {
  const { adapter, provider, history, range, timeoutMs = 2000 } = opts;
  const { entries } = await history.query(provider, adapter.name, range);
  const panelInput = {
    entries,
    range,
    truncated: false,
    esc,
    // 面板侧同注入共享图表工具（formatPanel 内 `const U = input.utils`）
    utils: ADAPTER_UTILS,
  };
  const formatted = await safeFormat(
    () => adapter.formatPanel(panelInput),
    "formatPanel",
    timeoutMs,
  );
  if (formatted.error !== undefined) return { error: formatted.error };
  return { panelHtml: sanitizeHtml(formatted.html ?? "") };
}

// ------------------------------------------------------------------ /history 渲染缓存（纯函数层）

/** 面板渲染缓存兜底 TTL：编译期常量，定界 [60s, 120s]。
 *  仅作兜底而非主失效机制——主失效是 append 落盘全清；取区间中值 90s。 */
export const PANEL_CACHE_TTL_MS = 90000;

/** 面板渲染缓存条目：runV2PanelPipeline 返回值字符串层快照。
 *  绝不缓存 entries 中间层（formatPanel 是用户代码，可能变异入参）。 */
export interface PanelCacheEntry {
  panelHtml?: string;
  error?: string;
  at: number;
}

/** 自然日粒度归一化：时间戳折算到当地时区当日零点。
 *  路由的 end=Date.now() 每请求漂移，key 含精确时间戳会令缓存永不命中。 */
export function normalizeRangeDay(range: { start: number; end: number }): {
  start: number;
  end: number;
} {
  const dayFloor = (t: number): number => {
    const d = new Date(t);
    d.setHours(0, 0, 0, 0);
    return d.getTime();
  };
  return { start: dayFloor(range.start), end: dayFloor(range.end) };
}

/** 缓存 key = provider + adapterName + 归一化 range。
 *  不同 days 参数归一化到不同自然日窗口 → 不同 key，互不串数据。 */
export function panelCacheKey(
  provider: string,
  adapterName: string,
  range: { start: number; end: number },
): string {
  const n = normalizeRangeDay(range);
  return `${provider}\u0000${adapterName}\u0000${n.start}\u0000${n.end}`;
}

/** TTL 兜底过期判定（严格大于；now/entry.at 分离入参便于单测注入时钟）。 */
export function isPanelCacheStale(
  entry: Pick<PanelCacheEntry, "at">,
  now: number,
  ttlMs: number = PANEL_CACHE_TTL_MS,
): boolean {
  return now - entry.at > ttlMs;
}

