/**
 * dsh-provider-usage — 适配器 mjs 热更新（mtime+size 轮询 + 原子切换）。
 *
 * 机制：
 * - 轮询 stat（默认 2s），对比 mtimeMs + size 检测文件变化（nodemon 同款，跨平台可靠）
 * - `import(pathToFileURL(file) + '?mtime=' + mtimeMs + '&size=' + size)` 绕 ESM 模块缓存。
 *   参数名刻意避开 `t=`：vite 系模块运行器（vitest）会把 `?t=<13 位毫秒>` 当时间戳剥离
 *   （`/\bt=\d{13}&?\b/`），只剩亚毫秒小数位参与模块标识；内核 coarse 时钟下同一 tick 的
 *   两次写入小数位相同，剥离后 URL 撞成同一个模块 → 缓存命中 → 热更新静默加载旧版。
 *   追加 size 同时覆盖「mtime 未变、内容长度已变」的重写。
 * - 新模块加载并校验通过后才替换引用（原子切换）；失败保留旧版
 * - 校验和（内容 hash）可选项：开启后每次变化先算 hash，文件被替换也能感知
 */
import { stat } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import type { UsageStatsAdapter } from "../../shared/interface.ts";
import { isUsageStatsAdapter, describeUsageStatsAdapterShape } from "../../shared/interface.ts";

/** 文件状态快照（mtimeMs + size）。 */
export interface FileStamp {
  mtimeMs: number;
  size: number;
}

/** 读取文件状态（不存在返回 null）。 */
export async function readStamp(file: string): Promise<FileStamp | null> {
  try {
    const s = await stat(file);
    return { mtimeMs: s.mtimeMs, size: s.size };
  } catch {
    return null;
  }
}

/** 两个快照是否相同。 */
export function stampEqual(a: FileStamp | null, b: FileStamp | null): boolean {
  if (a === null || b === null) return a === b;
  return a.mtimeMs === b.mtimeMs && a.size === b.size;
}

/** 加载 ESM 模块并校验为新契约（失败返回错误描述）。 */
export async function loadAndValidateAdapter(
  file: string,
  stamp: FileStamp,
): Promise<{ adapter?: UsageStatsAdapter; error?: string }> {
  try {
    const url = pathToFileURL(file).href + `?mtime=${stamp.mtimeMs}&size=${stamp.size}`;
    const mod = (await import(url)) as Record<string, unknown>;
    const candidate = (mod.default ?? mod) as unknown;
    if (!isUsageStatsAdapter(candidate)) {
      const detail = describeUsageStatsAdapterShape(candidate) ?? "未知形状问题";
      return { error: `契约校验失败：${detail}` };
    }
    return { adapter: candidate };
  } catch (e: unknown) {
    return { error: e instanceof Error ? e.message : String(e) };
  }
}

/**
 * 可热更新的适配器持有者。
 *
 * - `current`: 当前生效的适配器
 * - `poll()`: 轮询一次，文件变化则加载新版并原子切换
 * - `stop()`: 停止轮询
 */
export class HotReloadableAdapter {
  private timer: ReturnType<typeof setInterval> | null = null;
  private lastStamp: FileStamp | null = null;
  private readonly onReload: (info: { ok: boolean; error?: string }) => void;
  // 显式字段（构造器参数属性非可擦除语法，Node strip-only 模式
  // 无法加载插桩 src；改显式声明 + 构造函数体内赋值，语义零变化）
  private readonly file: string;
  private readonly intervalMs: number;
  private readonly checkChecksum: boolean;

  constructor(
    file: string,
    intervalMs: number,
    onReload?: (info: { ok: boolean; error?: string }) => void,
    checkChecksum = false,
  ) {
    this.file = file;
    this.intervalMs = intervalMs;
    this.checkChecksum = checkChecksum;
    this.onReload = onReload ?? ((): void => {});
  }

  /** 当前生效的适配器。 */
  current: UsageStatsAdapter | null = null;

  /** 启动轮询（先同步一次校验）。 */
  async start(): Promise<{ ok: boolean; error?: string }> {
    const stamp = await readStamp(this.file);
    this.lastStamp = stamp;
    if (stamp === null) {
      const error = `文件不存在或不可读：${this.file}`;
      this.onReload({ ok: false, error });
      return { ok: false, error };
    }
    const loaded = await this.reload(stamp);
    if (loaded.error !== undefined) {
      this.onReload({ ok: false, error: loaded.error });
      return loaded;
    }
    this.timer = setInterval(() => {
      void this.pollOnce();
    }, this.intervalMs);
    (this.timer as { unref?: () => void }).unref?.();
    return loaded;
  }

  /** 停止轮询（dispose 时调用）。 */
  stop(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /** 手动触发一次检轮询（测试用 / 启动补检）。 */
  async pollOnce(): Promise<{ ok: boolean; error?: string }> {
    const stamp = await readStamp(this.file);
    if (stampEqual(stamp, this.lastStamp)) return { ok: true };
    this.lastStamp = stamp;
    if (stamp === null) {
      // 文件被删除：保留当前适配器，不切换
      return { ok: true };
    }
    return this.reload(stamp);
  }

  private async reload(stamp: FileStamp): Promise<{ ok: boolean; error?: string }> {
    // 可选：校验和验证（内容 hash）——此处简化为记录 mtime+size，
    // 完整校验和需读文件内容；保持轻量，由调用方决定是否开启
    const loaded = await loadAndValidateAdapter(this.file, stamp);
    if (loaded.error !== undefined) {
      this.onReload({ ok: false, error: loaded.error });
      return { ok: false, error: loaded.error };
    }
    // 原子切换：新适配器校验通过后才替换引用
    this.current = loaded.adapter ?? null;
    this.onReload({ ok: true });
    return { ok: true };
  }
}

/**
 * dsh-provider-usage — 路径解析工具（M2 用户适配器注入）。
 *
 * 解析规则（同计划 3.2）：
 * 1. 行首 `~` / `~/`（含 Windows 反斜杠）→ 当前用户 home 展开（走 shared/dsh-home.js 接缝）。
 *    **`~user` 形态不展开**（见 expandHomePath）——它不是「当前用户 home」，展开它必须读真实
 *    home，会绕过 DSH_HOME 隔离。
 * 2. 绝对路径 → 原样。
 * 3. 相对路径 → 依次尝试相对 `DSH_HOME`（默认 `~/.dsh`）与相对插件 home
 *    （`~/.dsh/plugins/<plugin>`），先命中者胜。
 * 4. 解析后做 `existsSync` / 可读校验；失败 → 记诊断 + 该条目跳过。
 */
import { existsSync, statSync } from "node:fs";
import { isAbsolute, join } from "node:path";
import { dshHome as dshHomeBase, userHome } from "../../../../../shared/dsh-home.js";

/**
 * 插件 home 目录（host 文件逻辑归属区 ~/.dsh/plugins/provider-usage）。
 * 渐进退役 facade：base 缺省语义由 shared/dsh-home.js 单一事实源承载，
 * 公开签名不变——参数化供调用方在非全局 env 场景（如路由入参校验）复用。
 * @param base - DSH_HOME 根（缺省读 env，空串视同未设置，回落 ~/.dsh）。
 */
export function pluginHome(base = dshHomeBase()): string {
  return join(base, "plugins", "provider-usage");
}

/**
 * `~` 前缀展开（单一事实源：resolvePath 与 resolveAddAdapterFile 共用，
 * 保证「UI 承诺支持 ~ 路径」与校验行为一致）。
 *
 * 为什么自己展开而不复用 untildify（v6）：它除裸 `~` 外还展开 `~<当前登录用户>`——
 * 走 `os.homedir()` + `os.userInfo().username`，两者都读**进程级** environ/系统调用，
 * 绕开 shared/dsh-home.js 的接缝：隔离验证把 `HOME`/`DSH_HOME` 换掉之后，`~me/x` 仍会
 * 落到真实 home。这既违反本模块原本就写明的语义边界（`~user` 不展开、原样返回），
 * 也正是 `forbid-homedir-src` 门禁要拦的形态（该门禁一度为这一行开了豁免）。
 * `~user` 因此**一律原样返回**：它会被当作相对路径解析，解析不到就拒绝——UI placeholder
 * 只承诺 `~/.dsh/...`。
 * @param p - 原始路径。
 * @returns 展开后的路径（`~user` 与无前缀形态原样返回）。
 */
export function expandHomePath(p: string): string {
  // 取值次序与 shared/dsh-home.js 的 userHome() 一致：env 优先、空串视同未设置。
  if (/^~(?=$|[/\\])/.test(p)) return userHome() + p.slice(1);
  return p;
}

/**
 * 解析路径（支持 `~`、`~user`、绝对路径、相对 DSH_HOME/插件 home）。
 * @param p - 原始路径。
 * @returns 解析后的绝对路径，或 undefined（解析失败/文件不存在）。
 */
export function resolvePath(p: string): string | undefined {
  if (typeof p !== "string" || p.trim() === "") return undefined;
  const trimmed = p.trim();

  // 1. ~ 展开与绝对路径判定（expandHomePath 统一处理）
  const expandedHome = expandHomePath(trimmed);
  let expanded: string;
  if (expandedHome !== trimmed) {
    expanded = expandedHome;
  } else if (isAbsolute(trimmed)) {
    expanded = trimmed;
  } else {
    // 相对路径：尝试 DSH_HOME → 插件 home
    const dshHome = dshHomeBase();
    const candidates = [join(dshHome, trimmed), join(pluginHome(), trimmed)];
    for (const candidate of candidates) {
      if (existsSync(candidate)) {
        expanded = candidate;
        break;
      }
    }
    // 若无候选命中，取 DSH_HOME 相对路径（文件可能后续创建）
    expanded = join(dshHome, trimmed);
  }

  // 最终校验：可读
  if (!existsSync(expanded)) return undefined;

  // 检查是否为常规文件（非目录）
  try {
    if (!statSync(expanded).isFile()) return undefined;
  } catch {
    return undefined;
  }

  return expanded;
}

/**
 * dsh-provider-usage — 模型配置读取（V1 配置链 + DSH 凭据 seam 双层）。
 *
 * 密钥解析优先级（从高到低）：
 *   0. DSH 通用凭据 seam——由 configurable provider 目录驱动：读该 provider 的
 *      settings 命名空间（llm adapter 声明的 `apiKeyEnv` 凭据引用名），再经
 *      `credentials.resolve(ref)` 按 DSH 统一机制取值（env → .credentials.yaml
 *      refs → .env）。不猜环境变量名，与 llm 层同源同 key。
 *   1. 插件配置中的显式 apiKey
 *   2. 环境变量 {PROVIDER}_API_KEY（大写，连字符替换为下划线）
 *   3. opencode-go 兼容旧环境变量 OPENCODE_GO_API_KEY
 *   4. .credentials.yaml 文件：先查 {PROVIDER}_API_KEY 字段，opencode-go
 *      在标准 key 未命中时再查旧名 OPENCODE_GO_API_KEY
 *   5. auth.json 文件（仅 opencode-go 兼容）
 *
 * V1 链保留为兜底：opencode-go 默认 provider 不在 DSH configurable 目录，
 * seam 对 null 时须回落 V1 链，勿用 seam 替换。
 */
import { readFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { dshHome as dshHomeShared, userHome } from "../../../../../shared/dsh-home.js";

/** 插件配置提供的 apiEndpoint/apiKey（可选）。 */
export interface ProviderConfigInput {
  apiEndpoint?: string;
  apiKey?: string;
}

/** 读取并解析后的 provider 配置。 */
export interface ResolvedProviderConfig {
  apiEndpoint?: string;
  apiKey?: string;
}

/** 转义正则特殊字符。 */
function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** 从 .credentials.yaml 按 keyName 读取密钥。 */
function credentialsKeyFromYaml(text: string | undefined, keyName: string): string | undefined {
  if (typeof text !== "string") return undefined;
  const match = text.match(new RegExp(`${escapeRegex(keyName)}\\s*:\\s*["']?([^"'\r\n#]+)`, "u"));
  if (match === null) return undefined;
  const key = match[1].trim();
  return key.length > 0 ? key : undefined;
}

/** 从 auth.json 读取 opencode-go 兼容密钥。 */
function opencodeKeyFromAuth(text: string | undefined): string | undefined {
  if (typeof text !== "string") return undefined;
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    return undefined;
  }
  if (typeof data !== "object" || data === null) return undefined;
  const rec = data as Record<string, unknown>;
  const entry = (rec["opencode-go"] ?? rec["opencode"]) as Record<string, unknown> | undefined;
  if (entry && entry.type === "api" && typeof entry.key === "string" && entry.key.length > 0) {
    return entry.key;
  }
  return undefined;
}

/** .credentials.yaml 文件路径（DSH 官方凭据文档，dsh-credentials-local 同源：
 *  base 语义由 shared/dsh-home.js 承载）。 */
export function credentialsFile(dshHome?: string): string {
  return join(dshHome ?? dshHomeShared(), ".credentials.yaml");
}

/** auth.json 文件路径。 */
export function opencodeAuthFile(): string {
  // opencode 是 DSH_HOME 域外的第三方工具，凭据落点跟随用户 home（走共享接缝，
  // 使测试可用 process.env.HOME 隔离——见 shared/dsh-home.js 的 userHome 注释）。
  return join(userHome(), ".local", "share", "opencode", "auth.json");
}

/**
 * 解析 provider 配置（DSH 凭据 seam + V1 配置链兜底）。
 *
 * @param provider - provider 路由键。
 * @param ctx - 插件 apply 收到的 cordis 上下文；用于访问 llm/settings/credentials
 *   服务（经可选访问取用，缺席时回落 V1 链，不引入硬依赖）。
 * @param input - 插件配置提供（apiEndpoint/apiKey）。
 *
 * apiKey 解析优先级：
 *   0. DSH 凭据 seam（见 resolveViaCredentialSeam）
 *   1. 显式 input.apiKey
 *   2. 环境变量 {PROVIDER}_API_KEY
 *   3. opencode-go 兼容旧环境变量 OPENCODE_GO_API_KEY
 *   4. .credentials.yaml 的 {PROVIDER}_API_KEY（opencode-go 再查旧名）
 *   5. auth.json（仅 opencode-go）
 */
export async function resolveProviderConfig(
  provider: string,
  ctx?: unknown,
  input?: ProviderConfigInput,
): Promise<ResolvedProviderConfig> {
  const apiEndpoint = input?.apiEndpoint?.trim() || undefined;

  // 0. DSH 通用凭据 seam（最高优先，且不替换 V1 链）
  const seamKey = await resolveViaCredentialSeam(provider, ctx);
  if (seamKey !== undefined) return { apiEndpoint, apiKey: seamKey };

  // 1–5. V1 配置链兜底
  const apiKey = await resolveApiKey(provider, input?.apiKey);
  return { apiEndpoint, apiKey };
}

/**
 * DSH 通用凭据 seam：由 configurable provider 目录驱动，读 provider 的 settings
 * 命名空间（llm adapter 声明的 `apiKeyEnv` 凭据引用名），再经 `credentials.resolve`
 * 按 DSH 统一机制取值。沿线 `settingsPath` 下钻（覆盖 pi-ai 等嵌套命名空间）。
 * 任何环节缺席/无值一律返回 undefined（回落 V1 链），不抛错。
 */
async function resolveViaCredentialSeam(
  provider: string,
  ctx?: unknown,
): Promise<string | undefined> {
  const anyCtx = (ctx ?? {}) as {
    llm?: {
      listConfigurableProviders?: () => Array<{
        provider: string;
        settingsNs: string;
        settingsPath?: string[];
      }>;
    };
    get?: (name: string) => unknown;
  };
  if (typeof anyCtx.llm?.listConfigurableProviders !== "function") return undefined;

  const dir = anyCtx.llm.listConfigurableProviders().find((c) => c.provider === provider);
  if (dir === undefined) return undefined;

  const settings = anyCtx.get?.("settings") as { get?: (ns: string) => unknown } | undefined;
  const credentials = anyCtx.get?.("credentials") as
    { resolve?: (ref: string) => Promise<{ value?: string } | undefined> } | undefined;
  if (settings === undefined || typeof settings.get !== "function") return undefined;
  if (credentials === undefined || typeof credentials.resolve !== "function") return undefined;

  // 沿 settingsPath 下钻到 provider profile 对象
  let node: unknown = settings.get(dir.settingsNs);
  for (const seg of dir.settingsPath ?? []) {
    node = (node as Record<string, unknown> | undefined)?.[seg];
  }
  const ref = (node as { apiKeyEnv?: string } | undefined)?.apiKeyEnv;
  if (typeof ref !== "string" || ref.length === 0) return undefined;

  const got = await credentials.resolve(ref);
  if (got !== undefined && typeof got.value === "string" && got.value.length > 0) {
    return got.value;
  }
  return undefined;
}

/** 解析密钥（V1 配置链）。 */
async function resolveApiKey(provider: string, explicitKey?: string): Promise<string | undefined> {
  // 1. 显式配置优先
  if (typeof explicitKey === "string" && explicitKey.trim() !== "") return explicitKey.trim();

  // 2. 环境变量 {PROVIDER}_API_KEY
  const envVar = `${provider.toUpperCase().replace(/-/g, "_")}_API_KEY`;
  const env = process.env[envVar];
  if (typeof env === "string" && env.trim() !== "") return env.trim();

  // 3. opencode-go 兼容旧环境变量名
  if (provider === "opencode-go") {
    const legacy = process.env.OPENCODE_GO_API_KEY;
    if (typeof legacy === "string" && legacy.trim() !== "") return legacy.trim();
  }

  // 4. .credentials.yaml
  try {
    const credFile = credentialsFile();
    if (existsSync(credFile)) {
      const text = await readFile(credFile, "utf8");
      const fromYaml = credentialsKeyFromYaml(text, envVar);
      if (fromYaml !== undefined) return fromYaml;
      // opencode-go 兼容旧 key 名
      if (provider === "opencode-go") {
        const legacy = credentialsKeyFromYaml(text, "OPENCODE_GO_API_KEY");
        if (legacy !== undefined) return legacy;
      }
    }
  } catch {
    /* 忽略 */
  }

  // 5. auth.json（仅 opencode-go）
  if (provider === "opencode-go") {
    try {
      const authFile = opencodeAuthFile();
      if (existsSync(authFile)) {
        const text = await readFile(authFile, "utf8");
        const fromAuth = opencodeKeyFromAuth(text);
        if (fromAuth !== undefined) return fromAuth;
      }
    } catch {
      /* 忽略 */
    }
  }

  return undefined;
}

