    a.providers = [];
    expect(isUsageStatsAdapter(a)).toBe(false);
  });

  it("providers 元素非字符串拒绝", () => {
    const a = validAdapter();
    a.providers = [1];
    expect(isUsageStatsAdapter(a)).toBe(false);
  });

  it("providers 空串元素拒绝", () => {
    const a = validAdapter();
    a.providers = [""];
    expect(isUsageStatsAdapter(a)).toBe(false);
  });

  it("providers 多元素含空串拒绝", () => {
    const a = validAdapter();
    a.providers = ["p1", ""];
    expect(isUsageStatsAdapter(a)).toBe(false);
  });

  // 三函数条件
  for (const fn of ["fetchData", "formatCapsule", "formatPanel"] as const) {
    it(`缺 ${fn} 拒绝`, () => {
      const a = validAdapter();
      delete a[fn];
      expect(isUsageStatsAdapter(a)).toBe(false);
